 calls:=flag.Int("calls",5,"concurrent calls, 1..128");fail:=flag.Bool("panic",false,"initializer panics");flag.Parse()
 if *calls<1||*calls>128{fmt.Fprintln(os.Stderr,"calls must be 1..128");os.Exit(2)}
 var initialized,panics atomic.Int64;once:=practice.Once(func(){initialized.Add(1);if *fail && false{panic("broken")}})
 var group sync.WaitGroup
 for i:=0;i<*calls;i++{group.Add(1);go func(){defer group.Done();defer func(){if recover()!=nil{panics.Add(1)}}();once()}()}
 group.Wait();json.NewEncoder(os.Stdout).Encode(map[string]any{"initializations":initialized.Load(),"panics":panics.Load(),"calls":*calls})
}

