package main
import("encoding/json";"fmt";"io";"os";"practice")
func run()error{
 raw,err:=io.ReadAll(os.Stdin);if err!=nil{return err}
 var data struct{Capacity *int;Operations []struct{Op string;Value *int}}
 if err=json.Unmarshal(raw,&data);err!=nil{return err}
 if data.Capacity==nil||*data.Capacity<0||*data.Capacity>10000{return fmt.Errorf("capacity must be 0..10000")}
 for _,event:=range data.Operations{if event.Op!="offer"&&event.Op!="take"{return fmt.Errorf("unknown operation")};if event.Op=="offer"&&event.Value==nil{return fmt.Errorf("offer requires value")}}
 if data.Operations==nil{return fmt.Errorf("operations array required")}
 queue:=make(chan int,*data.Capacity+1);result:=[]map[string]any{}
 for _,event:=range data.Operations{
  if event.Op=="offer"{result=append(result,map[string]any{"op":"offer","accepted":practice.Offer(queue,*event.Value)})}else{
   select{case value:=<-queue:result=append(result,map[string]any{"op":"take","value":value});default:result=append(result,map[string]any{"op":"take","empty":true})}
  }
 }
 return json.NewEncoder(os.Stdout).Encode(result)
}
func main(){if err:=run();err!=nil{fmt.Fprintln(os.Stderr,err);os.Exit(2)}}

