package main
import("crypto/sha256";"encoding/hex";"encoding/json";"flag";"fmt";"io";"os";"path/filepath";"practice")
func run()error{
 source:=flag.String("source","","source file");output:=flag.String("output","","new output file");flag.Parse()
 if *source==""||*output==""{return fmt.Errorf("source and output required")}
 if _,err:=os.Lstat(*output);err==nil{return fmt.Errorf("output exists")}else if !os.IsNotExist(err){return err}
 input,err:=os.Open(*source);if err!=nil{return err};defer input.Close()
 temp,err:=os.CreateTemp(filepath.Dir(*output),".copy-");if err!=nil{return err};defer os.Remove(temp.Name());defer temp.Close()
 hash:=sha256.New();size,err:=practice.CopyBorrowed(io.MultiWriter(hash),input);if err!=nil{return err}
 if _,err=input.Stat();err!=nil{return err};if err=temp.Sync();err!=nil{return err};if err=temp.Close();err!=nil{return err}
 if err=os.Rename(temp.Name(),*output);err!=nil{return err}
 if err=json.NewEncoder(os.Stdout).Encode(map[string]any{"bytes":size,"sha256":hex.EncodeToString(hash.Sum(nil))});err!=nil{return fmt.Errorf("output committed; report failed: %w",err)}
 return nil
}
func main(){if err:=run();err!=nil{fmt.Fprintln(os.Stderr,err);os.Exit(2)}}
